3	const { spawn } = require('node:child_process');
4	const fs = require('node:fs/promises');
5	const { computeSummary } = require('./stats');
6	
7	const EXIT_OK = 0;
8	const EXIT_USAGE = 2;
9	const EXIT_MEASURE_ERROR = 3;
10	const EXIT_OUTPUT_ERROR = 4;
11	
12	const KNOWN_KEYS = new Set(['command', 'runs', 'warmup', 'timeout-ms', 'output']);
13	
14	// 解析 --key value / --key=value 形式的参数。
15	// knownKeys 为允许的参数名集合，缺省为 collect 的参数集。
16	// 返回 { values, error }；无法解析时 error 为说明字符串。
17	function parseArgs(tokens, knownKeys = KNOWN_KEYS) {
18	  const values = {};
19	  for (let i = 0; i < tokens.length; i++) {
20	    const token = tokens[i];
21	    if (!token.startsWith('--')) {
22	      return { values, error: `无法解析的参数: ${token}` };
23	    }
24	    const body = token.slice(2);
25	    const eq = body.indexOf('=');
26	    let key;
27	    let value;
28	    if (eq >= 0) {
29	      key = body.slice(0, eq);
30	      value = body.slice(eq + 1);
31	    } else {
32	      key = body;
33	      if (i + 1 >= tokens.length) {
34	        return { values, error: `参数 --${key} 缺少取值` };
35	      }
36	      value = tokens[++i];
37	    }
38	    if (!key) {
39	      return { values, error: `无法解析的参数: ${token}` };
40	    }
41	    if (!knownKeys.has(key)) {
42	      return { values, error: `未知参数: --${key}` };
43	    }
44	    if (Object.prototype.hasOwnProperty.call(values, key)) {
45	      return { values, error: `参数 --${key} 重复指定` };
46	    }
47	    values[key] = value;
48	  }
49	  return { values, error: null };
50	}
51	
52	function parsePositiveIntOption(values, key, { min, required }) {
53	  if (!Object.prototype.hasOwnProperty.call(values, key)) {
54	    if (required) return { error: `缺少必填参数 --${key}` };
55	    return { value: undefined };
56	  }
57	  const raw = values[key];
58	  // 仅接受十进制整数写法
59	  if (!/^-?\d+$/.test(raw)) {
60	    return { error: `参数 --${key} 必须为整数，实际为: ${raw}` };
61	  }
62	  const value = Number(raw);
63	  if (!Number.isSafeInteger(value) || value < min) {
64	    return { error: `参数 --${key} 必须为 >= ${min} 的整数，实际为: ${raw}` };
65	  }
66	  return { value };
67	}
68	
69	// 顺序执行一次目标命令。
70	// 返回 { startedAt, durationNs, exitCode, reason }
71	// reason 为 null 表示正常退出（exitCode 可能非零，由调用方按阶段处理），
72	// 或为 'timeout'；进程无法启动时抛错（error.code 通常为 ENOENT/EAGAIN）。
73	function runOnce(command, timeoutMs) {
74	  return new Promise((resolve, reject) => {
75	    let child;
76	    try {
77	      child = spawn(command, {
78	        shell: true,
79	        stdio: ['ignore', 'pipe', 'pipe'],
80	        // 非 Windows 下使子 shell 成为新进程组组长，超时可整组清理，避免遗留孙进程。
81	        detached: process.platform !== 'win32',
82	      });
83	    } catch (err) {
84	      reject(err);
85	      return;
86	    }
87	
88	    // 丢弃被测命令输出，保持本工具 stdout/stderr 干净，同时排空管道避免反压。
89	    child.stdout?.on('data', () => {});
90	    child.stderr?.on('data', () => {});
91	
92	    const startedAt = new Date();
93	    const startHr = process.hrtime.bigint();
94	    let settled = false;
95	    let timedOut = false;
96	
97	    const timer = setTimeout(() => {
98	      timedOut = true;
99	      try {
100	        if (child.pid && process.platform !== 'win32') {
101	          try {
102	            process.kill(-child.pid, 'SIGKILL');
103	          } catch {
104	            child.kill('SIGKILL');
105	          }
106	        } else {
107	          child.kill('SIGKILL');
108	        }
109	      } catch {
110	        // 进程可能已退出
111	      }
112	    }, timeoutMs);
113	    timer.unref?.();
114	
115	    child.on('error', (err) => {
116	      if (settled) return;
117	      settled = true;
118	      clearTimeout(timer);
119	      reject(err);
120	    });
121	
122	    child.on('close', (code, signal) => {
123	      if (settled) return;
124	      settled = true;
125	      clearTimeout(timer);
126	      const durationNs = Number(process.hrtime.bigint() - startHr);
127	      if (timedOut) {
128	        resolve({ startedAt, durationNs, exitCode: null, reason: 'timeout' });
129	        return;
130	      }
131	      // 被信号终止（非本工具超时）同样记为 nonzero_exit，exit_code 以 null 表示无可用退出码。
132	      resolve({ startedAt, durationNs, exitCode: code, signal, reason: null });
133	    });
134	  });
135	}
136	
137	function emptySummary() {
138	  return {
139	    count: 0,
140	    min: null,
141	    max: null,
142	    mean: null,
143	    median: null,
144	    p95: null,
145	    stddev: null,
146	  };
147	}
148	
149	// shell 下 127=命令未找到、126=命令不可执行，均属"进程无法启动"。
150	function isStartupExitCode(code) {
151	  return code === 126 || code === 127;
152	}
153	
154	// 启动失败：按 nonzero_exit 记录（而非 timeout）到 stderr；
155	// 按约定整体退出码 2，且不创建或改写 output。
156	function reportStartupFailure(stage, index, exitCode) {
157	  const record = { stage, index, reason: 'nonzero_exit', exit_code: exitCode };
158	  process.stderr.write(`perf-regress: 进程无法启动 ${JSON.stringify(record)}\n`);
159	}
160	
161	// 顺序执行单个采集场景：先 warmup 后 runs，全程不并发。
162	// 返回 { samples, errors, fatal }：
163	// fatal=true 表示发生进程无法启动（spawn 抛错或 shell 126/127），
164	// 已向 stderr 报告，调用方须以退出码 2 终止且不得写 output。
165	async function executeCase(command, runs, warmup, timeoutMs) {
166	  const samples = [];
167	  const errors = [];
168	
169	  // 先顺序预热：异常记录后继续；但进程无法启动属致命错误（退出码 2，不写 output）。
170	  for (let index = 0; index < warmup; index++) {
171	    let result;
172	    try {
173	      result = await runOnce(command, timeoutMs);
174	    } catch {
175	      reportStartupFailure('warmup', index, null);
176	      return { samples, errors, fatal: true };
177	    }
178	    if (result.reason === 'timeout') {
179	      errors.push({ stage: 'warmup', index, reason: 'timeout', exit_code: null });
180	    } else if (isStartupExitCode(result.exitCode)) {
181	      reportStartupFailure('warmup', index, result.exitCode);
182	      return { samples, errors, fatal: true };
183	    } else if (result.exitCode !== 0) {
184	      errors.push({ stage: 'warmup', index, reason: 'nonzero_exit', exit_code: result.exitCode });
185	    }
186	  }
187	
188	  // 再顺序采集：异常记录后跳过该次；进程无法启动则致命（退出码 2，不写 output）。
189	  for (let index = 0; index < runs; index++) {
190	    let result;
191	    try {
192	      result = await runOnce(command, timeoutMs);
193	    } catch {
194	      reportStartupFailure('measure', index, null);
195	      return { samples, errors, fatal: true };
196	    }
197	    if (result.reason === 'timeout') {
198	      errors.push({ stage: 'measure', index, reason: 'timeout', exit_code: null });
199	      continue;
200	    }
201	    if (isStartupExitCode(result.exitCode)) {
202	      reportStartupFailure('measure', index, result.exitCode);
203	      return { samples, errors, fatal: true };
204	    }
205	    if (result.exitCode !== 0) {
206	      errors.push({ stage: 'measure', index, reason: 'nonzero_exit', exit_code: result.exitCode });
207	      continue;
208	    }
209	    samples.push({
210	      index,
211	      started_at: result.startedAt.toISOString(),
212	      duration_ns: result.durationNs,
213	      exit_code: result.exitCode,
214	    });
215	  }
216	
217	  return { samples, errors, fatal: false };
218	}
219	
220	async function collect(tokens) {
221	  const { values, error: parseError } = parseArgs(tokens);
222	  if (parseError) {
223	    process.stderr.write(`perf-regress: ${parseError}\n`);
224	    return EXIT_USAGE;
225	  }
226	
227	  const command = values.command;
228	  const output = values.output;
229	  if (command === undefined || command === '') {
230	    process.stderr.write('perf-regress: --command 不能为空\n');
231	    return EXIT_USAGE;
232	  }
233	  if (output === undefined || output === '') {
234	    process.stderr.write('perf-regress: --output 不能为空\n');
235	    return EXIT_USAGE;
236	  }
237	
238	  const runsR = parsePositiveIntOption(values, 'runs', { min: 1, required: true });
239	  if (runsR.error) {
240	    process.stderr.write(`perf-regress: ${runsR.error}\n`);
241	    return EXIT_USAGE;
242	  }
243	  const warmupR = parsePositiveIntOption(values, 'warmup', { min: 0, required: false });
244	  if (warmupR.error) {
245	    process.stderr.write(`perf-regress: ${warmupR.error}\n`);
246	    return EXIT_USAGE;
247	  }
248	  const timeoutR = parsePositiveIntOption(values, 'timeout-ms', { min: 1, required: true });
249	  if (timeoutR.error) {
250	    process.stderr.write(`perf-regress: ${timeoutR.error}\n`);
251	    return EXIT_USAGE;
252	  }
253	
254	  const runs = runsR.value;
255	  const warmup = warmupR.value === undefined ? 0 : warmupR.value;
256	  const timeoutMs = timeoutR.value;
257	
258	  const { samples, errors, fatal } = await executeCase(command, runs, warmup, timeoutMs);
259	  if (fatal) {
260	    return EXIT_USAGE;
261	  }
262	
263	  const summary = samples.length === 0
264	    ? emptySummary()
265	    : computeSummary(samples.map((s) => s.duration_ns));
266	
267	  const report = {
268	    command,
269	    runs,
270	    warmup,
271	    timeout_ms: timeoutMs,
272	    unit: 'ns',
273	    samples,
274	    summary,
275	    errors,
276	  };
277	
278	  let payload;
279	  try {
280	    payload = JSON.stringify(report, null, 2) + '\n';
281	  } catch (err) {
282	    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
283	    return EXIT_OUTPUT_ERROR;
284	  }
285	
286	  try {
287	    await fs.writeFile(output, payload, 'utf8');
288	  } catch (err) {
289	    process.stderr.write(`perf-regress: 无法写入 --output ${output}: ${err.message}\n`);
290	    return EXIT_OUTPUT_ERROR;
291	  }
292	
293	  return errors.some((e) => e.stage === 'measure') ? EXIT_MEASURE_ERROR : EXIT_OK;
294	}
295	
296	module.exports = {
297	  collect,
298	  parseArgs,
299	  runOnce,
300	  executeCase,
301	  emptySummary,
302	  computeSummary,
303	  EXIT_OK,
304	  EXIT_USAGE,
305	  EXIT_MEASURE_ERROR,
306	  EXIT_OUTPUT_ERROR,
307	};
