1	'use strict';
2	
3	const fs = require('node:fs/promises');
4	const {
5	  parseArgs,
6	  executeCase,
7	  emptySummary,
8	  computeSummary,
9	  EXIT_OK,
10	  EXIT_USAGE,
11	  EXIT_MEASURE_ERROR,
12	  EXIT_OUTPUT_ERROR,
13	} = require('./collect');
14	
15	const KNOWN_KEYS = new Set(['manifest', 'output']);
16	
17	function fail(message) {
18	  process.stderr.write(`perf-regress: ${message}\n`);
19	  return EXIT_USAGE;
20	}
21	
22	// 读取并校验 collect-suite manifest：UTF-8 JSON 对象，cases 为非空数组；
23	// 每项 name 非空且唯一，command 非空，runs >= 1、warmup >= 0、timeout_ms >= 1
24	// 均为整数，未知字段忽略。返回 { cases } 或 { error }。
25	async function loadManifest(manifestPath) {
26	  let text;
27	  try {
28	    text = await fs.readFile(manifestPath, 'utf8');
29	  } catch (err) {
30	    return { error: `无法读取 manifest 文件 ${manifestPath}: ${err.message}` };
31	  }
32	  let manifest;
33	  try {
34	    manifest = JSON.parse(text);
35	  } catch {
36	    return { error: `manifest 文件不是合法 JSON: ${manifestPath}` };
37	  }
38	  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
39	    return { error: 'manifest 结构无效: 顶层须为对象' };
40	  }
41	  if (!Array.isArray(manifest.cases) || manifest.cases.length === 0) {
42	    return { error: 'manifest cases 必须为非空数组' };
43	  }
44	
45	  const cases = [];
46	  const names = new Set();
47	  for (let i = 0; i < manifest.cases.length; i++) {
48	    const item = manifest.cases[i];
49	    const where = `manifest cases[${i}]`;
50	    if (!item || typeof item !== 'object' || Array.isArray(item)) {
51	      return { error: `${where} 必须为对象` };
52	    }
53	    if (typeof item.name !== 'string' || item.name === '') {
54	      return { error: `${where} 的 name 必须为非空字符串` };
55	    }
56	    if (names.has(item.name)) {
57	      return { error: `manifest cases 中 name 重复: ${item.name}` };
58	    }
59	    if (typeof item.command !== 'string' || item.command === '') {
60	      return { error: `${where} (${item.name}) 的 command 必须为非空字符串` };
61	    }
62	    const intField = (key, min) => {
63	      if (!Number.isSafeInteger(item[key])) {
64	        return `${where} (${item.name}) 的 ${key} 必须为整数，实际为: ${JSON.stringify(item[key])}`;
65	      }
66	      if (item[key] < min) {
67	        return `${where} (${item.name}) 的 ${key} 必须为 >= ${min} 的整数，实际为: ${item[key]}`;
68	      }
69	      return null;
70	    };
71	    for (const e of [
72	      intField('runs', 1),
73	      intField('warmup', 0),
74	      intField('timeout_ms', 1),
75	    ]) {
76	      if (e) return { error: e };
77	    }
78	    names.add(item.name);
79	    cases.push({
80	      name: item.name,
81	      command: item.command,
82	      runs: item.runs,
83	      warmup: item.warmup,
84	      timeout_ms: item.timeout_ms,
85	    });
86	  }
87	  return { cases };
88	}
89	
90	async function collectSuite(tokens) {
91	  const { values, error: parseError } = parseArgs(tokens, KNOWN_KEYS);
92	  if (parseError) {
93	    return fail(parseError);
94	  }
95	
96	  const manifestPath = values.manifest;
97	  const output = values.output;
98	  if (manifestPath === undefined || manifestPath === '') {
99	    return fail('--manifest 不能为空');
100	  }
101	  if (output === undefined || output === '') {
102	    return fail('--output 不能为空');
103	  }
104	
105	  // 执行前完整校验：manifest 不合法直接退出 2，不创建或改写 output。
106	  const manifestR = await loadManifest(manifestPath);
107	  if (manifestR.error) {
108	    return fail(manifestR.error);
109	  }
110	
111	  // 按 cases 顺序采集，case 内先 warmup 后 runs，case 间不并发。
112	  const caseReports = [];
113	  for (const c of manifestR.cases) {
114	    const { samples, errors, fatal } = await executeCase(
115	      c.command, c.runs, c.warmup, c.timeout_ms);
116	    // 进程无法启动属致命错误：stderr 已由 executeCase 报告，不创建或改写 output。
117	    if (fatal) {
118	      return EXIT_USAGE;
119	    }
120	    const summary = samples.length === 0
121	      ? emptySummary()
122	      : computeSummary(samples.map((s) => s.duration_ns));
123	    const hasMeasureErrors = errors.some((e) => e.stage === 'measure');
124	    caseReports.push({
125	      name: c.name,
126	      command: c.command,
127	      runs: c.runs,
128	      warmup: c.warmup,
129	      timeout_ms: c.timeout_ms,
130	      unit: 'ns',
131	      samples,
132	      summary,
133	      errors,
134	      status: hasMeasureErrors ? 'measure_errors' : 'ok',
135	    });
136	  }
137	
138	  const suiteSummary = {
139	    total: caseReports.length,
140	    ok: caseReports.filter((c) => c.status === 'ok').length,
141	    measure_errors: caseReports.filter((c) => c.status === 'measure_errors').length,
142	    sample_count: caseReports.reduce((n, c) => n + c.samples.length, 0),
143	    error_count: caseReports.reduce((n, c) => n + c.errors.length, 0),
144	  };
145	
146	  const report = {
147	    cases: caseReports,
148	    suite_summary: suiteSummary,
149	  };
150	
151	  let payload;
152	  try {
153	    payload = JSON.stringify(report, null, 2) + '\n';
154	  } catch (err) {
155	    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
156	    return EXIT_OUTPUT_ERROR;
157	  }
158	
159	  try {
160	    await fs.writeFile(output, payload, 'utf8');
161	  } catch (err) {
