  const out = path.join(dir, 'existing.json');
  fs.writeFileSync(out, 'KEEP-ME');
  const r = runCli(['--command', 'true', '--runs', '0',
    '--timeout-ms', '5000', '--output', out]);
  assert.equal(r.status, 2);
