test('output 写入失败：退出码 4', () => {
  const out = path.join(withTempFile('no-such-dir'), 'nested', 'result.json');
  const r = runCli(['--command', 'true', '--runs', '1',
    '--timeout-ms', '5000', '--output', out]);
