});

test('measure 全部失败时 summary 各字段为 null 且 count 为 0', () => {
  const out = withTempFile('empty-summary.json');
  const r = runCli(['--command', 'exit 1', '--runs', '1',
    '--timeout-ms', '5000', '--output', out]);
  assert.equal(r.status, 3);
